from pathlib import Path

ROOT = Path(__file__).resolve().parent
SITE = ROOT / "site"
DOMAIN = "https://septicscope.com"
GA_MEASUREMENT_ID = "G-F6RB8YERCM"

STYLE = r'''
:root{--ink:#17212b;--muted:#5b6672;--line:#dce3e8;--panel:#f7fafb;--accent:#176b5b;--soft:#eaf5f1;--warm:#fff8ed}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);line-height:1.72;background:#fff}a{color:var(--accent)}header{border-bottom:1px solid var(--line)}.nav,main,.footer-inner{max-width:980px;margin:auto;padding:20px 24px}.nav{display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{font-weight:900;color:var(--ink);text-decoration:none}.nav-links{display:flex;gap:16px;flex-wrap:wrap}.nav-links a{text-decoration:none;font-weight:750}main{padding-top:42px;padding-bottom:74px}.crumb{font-size:.91rem;color:var(--muted)}h1{font-size:clamp(2.25rem,5vw,3.9rem);line-height:1.05;letter-spacing:-.035em;margin:.45em 0 .35em}h2{font-size:clamp(1.45rem,3vw,2rem);line-height:1.2;margin-top:2em}h3{margin-top:1.5em}.lede{font-size:1.16rem;color:#3f4b55;max-width:780px}.editorial{border:1px solid var(--line);border-radius:14px;background:var(--panel);padding:14px 16px;margin:22px 0;color:var(--muted);font-size:.92rem}.summary,.note,.checklist{border:1px solid var(--line);border-radius:16px;padding:20px;margin:28px 0}.summary{background:var(--soft)}.note{background:var(--warm)}.checklist{background:#fff}.checklist li{margin:.55em 0}.record-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:22px 0}.record-card{border:1px solid var(--line);border-radius:14px;padding:17px;background:var(--panel)}.record-card h3{margin:0 0 8px}.record-card p{margin:0;color:var(--muted)}table{border-collapse:collapse;width:100%;margin:22px 0}th,td{border:1px solid var(--line);padding:12px;text-align:left;vertical-align:top}th{background:var(--panel)}.print-button{border:0;border-radius:10px;background:var(--accent);color:white;padding:11px 15px;font:800 1rem inherit;cursor:pointer}footer{border-top:1px solid var(--line);color:var(--muted)}@media(max-width:700px){.record-grid{grid-template-columns:1fr}.nav{display:block}.nav-links{margin-top:10px}table{display:block;overflow-x:auto}}@media print{header,footer,.print-button{display:none}main{max-width:none;padding:0}.summary,.note,.checklist,.record-card{break-inside:avoid}}
'''


def build() -> None:
    out = SITE / "guides" / "find-septic-system-records"
    out.mkdir(parents=True, exist_ok=True)
    canonical = f"{DOMAIN}/guides/find-septic-system-records/"
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>How to Find Septic System Records, Permits and As-Built Plans</title><meta name="description" content="A step-by-step guide to finding septic permits, as-built drawings, inspection records, repair histories and maintenance documents through the correct local office."><link rel="canonical" href="{canonical}"><meta property="og:type" content="article"><meta property="og:title" content="How to Find Septic System Records"><meta property="og:description" content="Find the correct local office, request the right record types and understand what a missing file does—and does not—mean."><meta property="og:url" content="{canonical}"><style>{STYLE}</style><script async src="https://www.googletagmanager.com/gtag/js?id={GA_MEASUREMENT_ID}"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag('js',new Date());gtag('config','{GA_MEASUREMENT_ID}');</script><script type="application/ld+json">{{"@context":"https://schema.org","@type":"HowTo","name":"How to find septic system records","description":"A practical process for locating septic permits, plans, inspections and maintenance records.","publisher":{{"@type":"Organization","name":"SepticScope","url":"{DOMAIN}/"}},"mainEntityOfPage":"{canonical}"}}</script></head><body><header><div class="nav"><a class="brand" href="/">SepticScope</a><nav class="nav-links" aria-label="Primary"><a href="/counties/">County lookup</a><a href="/guides/">Guides</a><a href="/faq/">FAQs</a><a href="/about/">Research standards</a></nav></div></header><main><p class="crumb"><a href="/">Home</a> / <a href="/guides/">Guides</a> / Septic system records</p><h1>How to find septic system records, permits and as-built plans</h1><p class="lede">The fastest way to find a septic record is usually not a broad internet search. It is to identify the property’s legal jurisdiction, learn which office held onsite-wastewater files when the system was permitted, and ask for the specific documents that office is likely to maintain.</p><div class="editorial"><strong>Published by the SepticScope Editorial Desk.</strong> This guide explains a research process, not a universal records law. Access rules, retention schedules, fees and available document types vary by jurisdiction. Use the official county or state sources linked from the applicable SepticScope county guide.</div><div class="summary"><strong>The practical sequence</strong><ol><li>Confirm the parcel and legal county.</li><li>Identify the current onsite-wastewater authority.</li><li>Ask for several record types, not only “the septic permit.”</li><li>Search by every identifier the office accepts.</li><li>Escalate to an open-records request only when ordinary lookup methods fail.</li><li>Treat a missing file as an information gap—not proof that no system or permit exists.</li></ol></div><button class="print-button" type="button" onclick="window.print()">Print this records checklist</button>

<h2>1. Start with the property record, not the mailing address</h2><p>A mailing city and ZIP code can cross county or municipal boundaries. Septic regulation may be handled by a county environmental-health office, a regional health district, a municipality, a state environmental agency or a delegated program. Begin with the assessor, appraisal district, recorder or other official property source and confirm the parcel number, situs address and legal county. The <a href="/counties/">SepticScope county and FIPS lookup</a> can help identify the likely county, but the property record controls when boundaries are uncertain.</p><p>Write down all useful identifiers before contacting an agency: parcel or assessor number, current street address, older address formats, subdivision name, lot and block, owner names, builder name and approximate construction year. Older septic files may be indexed under an owner or legal description rather than the modern street address.</p>

<h2>2. Identify both the current authority and the historical record holder</h2><p>The office that regulates septic work today may not be the office that issued a permit decades ago. Programs can move between county departments, health districts and state agencies. Ask the current onsite-wastewater authority whether it holds historical files and, if not, where older records were transferred. A planning or building department may also have a building-permit packet that references the septic approval even when the detailed onsite file is elsewhere.</p><div class="record-grid"><article class="record-card"><h3>Current regulatory office</h3><p>Useful for present permit requirements, repair authorization, operating permits, maintenance rules and the location of current records.</p></article><article class="record-card"><h3>Building or planning office</h3><p>May hold site plans, certificate-of-occupancy documents, subdivision files or permit cross-references.</p></article><article class="record-card"><h3>Recorder, clerk or assessor</h3><p>Useful for legal descriptions, recorded easements, parcel history and ownership names used in older indexes.</p></article><article class="record-card"><h3>Prior owner or service company</h3><p>May have pumping receipts, inspection reports, maintenance contracts, riser locations or repair invoices that never entered a government file.</p></article></div>

<h2>3. Ask for the right documents</h2><p>“Do you have my septic record?” can produce an incomplete answer because agencies use different names for the same file. Ask whether the office can search for each of the following:</p><table><thead><tr><th>Record type</th><th>What it may show</th><th>Important limitation</th></tr></thead><tbody><tr><td>Construction or installation permit</td><td>Approved system type, design flow, bedroom basis, installer, permit date and conditions.</td><td>The approved design does not prove the system was installed exactly as drawn.</td></tr><tr><td>As-built, record drawing or installation sketch</td><td>Tank, treatment unit, distribution components and drainfield location after installation.</td><td>Accuracy varies, especially for older hand-drawn sketches.</td></tr><tr><td>Soil or site evaluation</td><td>Test locations, soil conditions, limiting features, slope and proposed treatment area.</td><td>It describes evaluated conditions and may not map every later alteration.</td></tr><tr><td>Final inspection or approval</td><td>Inspection date, approval status, corrections and authorization to cover or use the system.</td><td>Some jurisdictions retained only a summary rather than a full report.</td></tr><tr><td>Repair or alteration permit</td><td>Replacement tanks, drainfield repairs, added components or changes in design capacity.</td><td>Unpermitted work may not appear in the file.</td></tr><tr><td>Operating permit or maintenance report</td><td>Advanced-system inspections, service visits, alarms, sampling or maintenance-provider information.</td><td>Routine records may be retained for a limited period.</td></tr><tr><td>Complaint or enforcement record</td><td>Reported failures, notices, corrective actions or unresolved issues.</td><td>Availability and disclosure can be restricted by local law.</td></tr></tbody></table>

<h2>4. Search with more than one identifier</h2><p>When an online portal returns nothing, change the search method before concluding that no record exists. Try the parcel number with and without punctuation, street number only, former owner names, subdivision and lot, permit number from another document, and alternate spellings of the street. Ask staff whether records were digitized completely or whether older paper, microfilm or archived files require a manual search.</p><p>For a recent home purchase, the title file, seller disclosure, prior inspection report and appraisal may contain a permit number or sketch. A pumping company may have a service history tied to the customer name rather than the property address. Those private records are useful leads, but they do not replace the official file or a current inspection.</p>

<h2>5. Make a focused public-records request when necessary</h2><p>If normal customer-service channels do not locate the file, ask the agency how to submit a public-records request. Keep it narrow enough to search. Identify the parcel, address, date range and document categories. A request such as “all septic records” may be slower or less precise than a request for construction permits, site evaluations, as-built drawings, final inspections, repairs and operating reports associated with a named parcel.</p><div class="note"><strong>Sample request language</strong><p>Please provide existing onsite wastewater or septic records associated with [property address and parcel number], including construction or repair permits, site or soil evaluations, approved plans, as-built or record drawings, final inspections, operating permits and maintenance reports. The approximate construction year is [year], and prior owners may include [names]. Electronic copies are preferred.</p></div><p>Public-records laws generally require agencies to provide existing responsive records; they do not require staff to create a new drawing, certify the current condition of the system or resolve conflicting documents. Fees, redactions and response times vary.</p>

<h2>6. Know what a missing record means</h2><p>A missing file can result from age, retention practices, incomplete digitization, address changes, jurisdiction changes, fire or water damage, unpermitted work, or a system that predates modern permitting. It does not prove that the property has no septic system, that the installation was legal, or that the system is functioning.</p><p>When the location or condition matters—for example during a home sale, repair, addition or excavation—combine records research with appropriate field work. A qualified inspector or service provider may use accessible-component inspection, probing, locating equipment, camera work or other lawful methods. Do not enter a septic tank, and do not rely on a sketch alone before digging.</p>

<h2>7. Read the file as a history, not a warranty</h2><p>Compare dates, addresses, parcel identifiers and system descriptions across documents. A later repair permit may supersede the original plan. Bedroom additions or lot changes may affect design assumptions. A final approval indicates what the agency accepted at that time; it is not a current performance guarantee. Maintenance records can show service history, but an absence of receipts does not establish that maintenance never occurred.</p><p>Keep the complete file together and add new inspection reports, pumping receipts, component replacements and photographs. Note dimensions from fixed landmarks rather than relying only on temporary landscaping. Good records reduce unnecessary excavation and make future permit, sale and repair decisions easier.</p>

<div class="checklist"><h2>Septic records checklist</h2><ul><li>Legal county and municipality confirmed from an official property record</li><li>Parcel, assessor or appraisal-district number</li><li>Current and former street-address formats</li><li>Subdivision, lot, block and legal description</li><li>Current and former owner names</li><li>Approximate home and septic construction dates</li><li>Construction and repair permits requested</li><li>Site or soil evaluation requested</li><li>Approved plan and as-built drawing requested</li><li>Final inspection or authorization requested</li><li>Operating and maintenance records requested when applicable</li><li>Building, planning and recorder cross-check completed</li><li>Seller, inspector, installer and pumper records checked</li><li>Documents saved with dates and source information</li></ul></div>

<h2>Official starting points</h2><ul><li><a href="https://www.usa.gov/state-local-governments" rel="nofollow noopener">USA.gov state and local government directory</a> — find official state, county and municipal websites.</li><li><a href="https://www.epa.gov/septic/state-septic-system-program-contacts" rel="nofollow noopener">U.S. EPA state septic program contacts</a> — identify the state-level onsite-wastewater program or contact.</li><li><a href="https://www.epa.gov/septic" rel="nofollow noopener">U.S. EPA septic system resources</a> — general homeowner information and SepticSmart materials.</li></ul><p><em>SepticScope summarizes a research process for informational purposes. The records custodian’s current procedures and applicable public-records law control.</em></p></main><footer><div class="footer-inner">© 2026 SepticScope · <a href="/about/">About our research</a> · <a href="/privacy/">Privacy</a> · <a href="/contact/">Corrections &amp; feedback</a></div></footer></body></html>'''
    (out / "index.html").write_text(page, encoding="utf-8")
    if page.lower().count("<h1") != 1 or len(page.split()) < 900:
        raise RuntimeError("Septic records guide did not meet the publication threshold")
    print("Published substantive septic system records guide")


if __name__ == "__main__":
    build()
